def comb_sort(arr):
    if len(arr) <= 1:
        return arr

    n = len(arr)
    gap = n
    swapped = True

    while swapped:
        swapped = False

        for i in range(0, n - gap):
            if arr[i] > arr[i + gap]:
                # Swap elements
                temp = arr[i]
                arr[i] = arr[i + gap]
                arr[i + gap] = temp

                # If a swap occurred, reset the shrink factor to ensure all gaps are checked in this pass
                if i >= n - 2 * gap:
                    swapped = True

        # Update the gap for next iteration (shrink by ~1.3)
        gap = int(gap / 1.3)

    return arr

